INSERT INTO `services` VALUES (1,'Virtual CFO Services','virtual-cfo-services','Strategic financial leadership on demand — budgeting, forecasting, and cash flow management without a full-time hire.','<p>At Dev Mantra, our Virtual CFO services provide your business with strategic financial leadership without the overhead of a full-time CFO. Our experienced professionals work closely with your team to deliver comprehensive financial management.</p><h3>What We Offer</h3><ul><li>Monthly Financial Reporting & Analysis</li><li>Budgeting & Forecasting</li><li>Cash Flow Management & Optimization</li><li>Financial Strategy & Planning</li><li>Investor Relations & Fundraising Support</li><li>Board Reporting & Governance</li></ul><h3>Why Choose a Virtual CFO?</h3><p>Growing businesses need strategic financial guidance but may not require or afford a full-time CFO. Our Virtual CFO service bridges this gap, providing C-suite financial expertise on a flexible, scalable basis.</p>','fa-solid fa-chart-line','services/XpKZS9iV1n5399qdVigoPKzgE4vKqOv5BgaNGa6Y.jpg','services/yWjaERnfJutVfMDlC1lapvZXj6qYwVWxg4dNAc4a.jpg','services/T3h1QpnBZ37FYT17C7pkwNmxHHMybHGpu2RDdA3o.jpg',NULL,1,6,'published',NULL,'2026-03-01 23:10:54','2026-03-17 23:49:20',NULL,NULL,NULL,0,NULL),(2,'Finance Accounts Compliance Outsourcing Services','finance-accounts-compliance-outsourcing-services','End-to-end outsourcing for bookkeeping, accounts payable/receivable, and regulatory compliance across jurisdictions.','<p>At Dev Mantra, we use state-of-the-art accounting software and proven methodologies to deliver effortless bookkeeping and accounting services. Our team ensures your financial records are accurate, compliant, and up-to-date.</p><h3>Core Services</h3><ul><li>Accounts and BookKeeping — Voucher Entry, General Ledger Adjustments, MIS Preparation</li><li>Payroll Accounting — Salary Processing, PF/ESI Compliance, TDS on Salary</li><li>Tax Planning & Strategy — Direct and Indirect Tax Planning</li><li>International Taxation — Transfer Pricing, DTAA Advisory</li><li>Regulatory & Compliance Advisory — GST, Companies Act, SEBI Compliance</li></ul>','fa-solid fa-book','services/zK1cIpJrGAgF3axW4nl4YSo5TOTAkRY4tTknvHfJ.webp','services/qoB8rEmsdbIIt9FilcojZnEa34ypBDekohsmD9Rl.webp','services/vTOsuGUuYKZKbK6vvrZhBHgH3nTfuQgDdomXRnlr.webp',NULL,1,7,'published',NULL,'2026-03-01 23:10:54','2026-03-17 23:49:53',NULL,NULL,NULL,0,NULL),(3,'Deals, Due Diligence & Transaction Advisory','deals-due-diligence-transaction-advisory','Thorough financial, legal, and operational due diligence to ensure informed investment and acquisition decisions.','<p>Our Deals and Due Diligence team provides comprehensive transaction advisory services that help you make informed decisions. Whether you\'re acquiring a business, merging operations, or divesting assets, we deliver the insights you need.</p><h3>Our Approach</h3><ul><li>Financial Due Diligence — Quality of earnings, working capital analysis</li><li>Tax Due Diligence — Tax exposure assessment, compliance review</li><li>Legal Due Diligence — Contract review, regulatory compliance</li><li>Operational Due Diligence — Process evaluation, synergy assessment</li><li>Valuation Services — Business valuation, fairness opinions</li></ul>','fa-solid fa-magnifying-glass-chart','services/YJ5u6TGrQ6QUdF6MSZ0QkbBYFz7vuIf5q7etvmnB.jpg','services/9KJVR7WG3Jj05o0YeRTBLyloEBMakxZsSIDPdtHK.jpg','services/10SJOY8iMm4B1pflyaQ1cC8N3vYuRiMnlScwpu62.jpg',NULL,1,2,'published',NULL,'2026-03-01 23:10:54','2026-03-17 23:49:37',NULL,NULL,NULL,0,NULL),(4,'Business Set Up & Startup Collaboration','business-set-up-startup-collaboration','From entity formation to fundraising support, we help startups launch with the right structure and strategy.','<p>Dev Mantra supports entrepreneurs and businesses in setting up operations in India and abroad. From entity formation to regulatory compliance, we ensure your business starts on the right foundation.</p><h3>Services Include</h3><ul><li>Company Incorporation — Private Limited, LLP, OPC</li><li>Foreign Subsidiary Setup in India</li><li>Startup India Registration & DPIIT Recognition</li><li>Fundraising & Pitch Deck Support</li><li>Accounting & Compliance Setup from Day 1</li></ul>','fa-solid fa-rocket','services/LvVgxgzQLICYZh8XQ3k4zBbCaGQVC7CbS3ONcq1Y.jpg','services/Uc1YFOdEzqSRSLeufndFFgw2RXLsRlntLKYRLpqD.jpg','services/0N7ldQXVRc04vSCZhhoSDqIZpx2L47TsUFgGRTbr.jpg',NULL,1,5,'published',NULL,'2026-03-01 23:10:54','2026-03-17 23:50:21',NULL,NULL,NULL,0,NULL),(5,'IPO Advisory Services','ipo-advisory-services','Guiding companies through every stage of going public — from pre-IPO readiness to listing and beyond.','<p>Our IPO Advisory practice guides companies through every stage of the public listing journey. From pre-IPO readiness assessment to post-listing compliance, we ensure a smooth transition to the public markets.</p><h3>Our IPO Services</h3><ul><li>IPO Readiness Assessment</li><li>Financial Restructuring & Audit Preparation</li><li>DRHP/RHP Preparation Support</li><li>SEBI & Stock Exchange Liaison</li><li>Post-IPO Compliance & Reporting</li></ul>','fa-solid fa-arrow-trend-up','services/IyBLrrqePha9wESl3POZMEpfUFrhBpG0vgp8yTcH.webp','services/KCJp4evB37fGiJRFIPGkoshyoHutD9FqIcfse1G2.webp','services/tvdawl8lL1sA7V7SKGeCREDZn9UB0bftZX0ddvCV.webp',NULL,1,4,'published',NULL,'2026-03-01 23:10:54','2026-03-17 23:48:50',NULL,NULL,NULL,0,NULL),(6,'Corporate Governance','corporate-governance','Establishing governance frameworks, board advisory, and compliance programs to build stakeholder confidence.','<p>Strong corporate governance is the backbone of sustainable business growth. Dev Mantra helps organizations establish robust governance frameworks that build trust with stakeholders and ensure regulatory compliance.</p><h3>Governance Services</h3><ul><li>Board Advisory & Composition Strategy</li><li>Corporate Governance Framework Design</li><li>SEBI LODR Compliance</li><li>ESG & Sustainability Reporting</li><li>Whistleblower Policy & Ethics Framework</li><li>Annual Compliance Calendar Management</li></ul>','fa-solid fa-building-columns','services/b9DK6N0xW6LZL87OgWwxhTtjPpfc1wE39n9SX4Da.jpg','services/NGwabh1bIEeIXIJuFhSjtPRaCy55t79N1AAC8mD8.jpg','services/h58GLXsKFex1q98DRoRkZasKMoqjxu6yfttkHVwE.jpg',NULL,1,9,'published',NULL,'2026-03-01 23:10:54','2026-03-17 23:50:39',NULL,NULL,NULL,0,NULL),(7,'GCC (Global Capability Centers)','gcc-global-capability-centers','Setting up and scaling offshore capability centers with operational excellence and talent strategies.','<p>India has emerged as the global hub for capability centers. Dev Mantra helps multinational corporations set up, scale, and optimize their Global Capability Centers in India.</p><h3>GCC Services</h3><ul><li>GCC Strategy & Feasibility Study</li><li>Entity Setup & Regulatory Compliance</li><li>Talent Acquisition & HR Framework</li><li>Finance & Accounting Operations Setup</li><li>Technology Infrastructure Advisory</li><li>Ongoing Compliance & Governance</li></ul>','fa-solid fa-globe','services/loVDdRmAhwzl49LDv9qPQp9tCvTGwFCcbcxyyMG9.jpg','services/9vWAskeAE2SfBtpdiAcujA0JO1rHcoszzjQBw6ce.jpg','services/mEEyqmeRNd7N8H5ZuDVYjmL90ixDhMYWo4tjN2Yg.jpg',NULL,1,3,'published',NULL,'2026-03-01 23:10:54','2026-03-17 23:48:40',NULL,NULL,NULL,0,NULL),(8,'M & A Advisory Services','m-a-advisory-services','Full-cycle mergers and acquisitions support — target identification, valuation, negotiation, and post-merger integration.','<p>Dev Mantra\'s M&A Advisory practice supports businesses through every stage of the merger and acquisition lifecycle. Our team combines financial expertise with strategic insight to maximize deal value.</p><h3>M&A Services</h3><ul><li>Target Identification & Screening</li><li>Business Valuation & Financial Modeling</li><li>Deal Structuring & Negotiation Support</li><li>Due Diligence Management</li><li>Post-Merger Integration Planning</li><li>Cross-Border M&A Advisory</li></ul>','fa-solid fa-handshake','services/vBnU3ZRrF6M3NrxdCJToi3RdhqNRNbsVbCXDnv1J.jpg','services/0AdN8kPXCMR7yRBTOXTi5IGjdNw71HrrlcgjJh50.jpg','services/i103uUBHPXJsOtTqCwpxneh41UDwFlvHIe2XPnZd.jpg',NULL,1,1,'published',NULL,'2026-03-01 23:10:54','2026-03-17 23:48:18',NULL,NULL,NULL,0,NULL),(9,'Risk Advisory & Augmenting Business Process','risk-advisory-augmenting-business-process','Identifying and mitigating business risks while optimizing operations for efficiency and scalability.','<p>In an increasingly complex business environment, proactive risk management is essential. Dev Mantra\'s Risk Advisory services help organizations identify, assess, and mitigate risks across all business functions.</p><h3>Risk Advisory Services</h3><ul><li>Enterprise Risk Management Framework</li><li>Internal Audit & Controls Assessment</li><li>Fraud Risk Assessment & Investigation</li><li>IT Risk & Cybersecurity Advisory</li><li>Business Continuity Planning</li><li>Process Optimization & Automation</li></ul>','fa-solid fa-shield-halved','services/ckqbJLm5kTXxqewAmLSy1Gohrp6QKethQsizAkoq.png','services/rtg6I4g4VdpQz3ViiF5NfngJjTy2oalSEx0NeRUz.png','services/lJssXtAPXyp7pd0XYVaKr2h6VZmNMBPinPWBCL0v.png',NULL,1,8,'published',NULL,'2026-03-01 23:10:54','2026-03-17 23:50:50',NULL,NULL,NULL,0,NULL);
